1280	        ) {
1281	          unlockedJobs.push(j);
1282	        }
1283	      }
1284	    }
1285	    var pendingJobs = [];
1286	    if (typeof STREET_JOBS !== "undefined") {
1287	      for (var pji = 0; pji < STREET_JOBS.length; pji++) {
1288	        var pj = STREET_JOBS[pji];
1289	        if (
1290	          pj.requirements &&
1291	          pj.requirements[key] &&
1292	          skill.level < pj.requirements[key]
1293	        ) {
1294	          pendingJobs.push({ name: pj.name, need: pj.requirements[key] });
1295	        }
1296	      }
1297	    }
1298	
1299	    var card = document.createElement("div");
