1307	      jobHtml =
1308	        '<div style="font-size:9px;color:var(--success);margin-top:4px;">✅ 解锁: ' +
1309	        unlockedJobs
1310	          .slice(0, 3)
1311	          .map(function (jj) {
1312	            return jj.name;
1313	          })
1314	          .join(" / ") +
1315	        "</div>";
1316	    }
1317	    for (var kji = 0; kji < pendingJobs.length && kji < 3; kji++) {
1318	      var pp = pendingJobs[kji];
1319	      jobHtml +=
1320	        '<div style="font-size:9px;color:var(--text-muted);margin-top:2px;">🔒 ' +
1321	        pp.name +
1322	        "(≥Lv." +
1323	        pp.need +
1324	        ")</div>";
1325	    }
1326	
1327	    card.innerHTML =
1328	      '<div class="card-title">' +
1329	      name +
1330	      "</div>" +
