function renderSkillsTab(state, parent) {
  parent.innerHTML = "";
  var div = document.createElement("div");
  div.innerHTML =
    '<h3 style="color:var(--text-muted);margin-bottom:12px;">📚 技能 <span style="font-size:11px;color:var(--accent);">⚡10+💰¥20 = 训练一次</span></h3>';

  var grid = document.createElement("div");
  grid.className = "action-cards";
  grid.style.gridTemplateColumns = "repeat(auto-fill, minmax(200px, 1fr))";

  var skillNames = {
    cooking: "🍳 烹饪",
    repair: "🔧 维修",
    coding: "💻 编程",
    english: "🌐 英语",
    driving: "🚗 驾驶",
    sales: "💼 销售",
    management: "📋 管理",
    accounting: "📊 会计",
    electrician: "⚡ 电工",
    welding: "🔥 焊接",
  };
  var skillNamesCache = skillNames;

  var skillKeys = Object.keys(state.skills);
  for (var ki = 0; ki < skillKeys.length; ki++) {
    var key = skillKeys[ki];
    var skill = state.skills[key];
    var name = skillNames[key] || key;
    var xpNeeded = (skill.level + 1) * 100;
    var xpPct = Math.min(100, Math.round((skill.xp / xpNeeded) * 100));

    // 工作解锁检查
    var unlockedJobs = [];
    if (typeof STREET_JOBS !== "undefined") {
      for (var ji = 0; ji < STREET_JOBS.length; ji++) {
        var j = STREET_JOBS[ji];
        if (
          j.requirements &&
          j.requirements[key] &&
          skill.level >= j.requirements[key]
        ) {
          unlockedJobs.push(j);
        }
      }
    }
    var pendingJobs = [];
    if (typeof STREET_JOBS !== "undefined") {
      for (var pji = 0; pji < STREET_JOBS.length; pji++) {
        var pj = STREET_JOBS[pji];
        if (
          pj.requirements &&
          pj.requirements[key] &&
          skill.level < pj.requirements[key]
        ) {
          pendingJobs.push({ name: pj.name, need: pj.requirements[key] });
        }
      }
    }

    var card = document.createElement("div");
    card.className = "action-card";
    card.style.cursor = "pointer";
    card.setAttribute("data-skill", key);
    card.title = "⚡10+💰¥20 = 训练" + name;

    var jobHtml = "";
    if (unlockedJobs.length > 0) {
      jobHtml =
        '<div style="font-size:9px;color:var(--success);margin-top:4px;">✅ 解锁: ' +
        unlockedJobs
          .slice(0, 3)
          .map(function (jj) {
            return jj.name;
          })
          .join(" / ") +
        "</div>";
    }
    for (var kji = 0; kji < pendingJobs.length && kji < 3; kji++) {
      var pp = pendingJobs[kji];
      jobHtml +=
        '<div style="font-size:9px;color:var(--text-muted);margin-top:2px;">🔒 ' +
        pp.name +
        "(≥Lv." +
        pp.need +
        ")</div>";
    }

    card.innerHTML =
      '<div class="card-title">' +
      name +
      "</div>" +
      '<div class="card-desc">Lv.' +
      skill.level +
      " / 100</div>" +
      '<div style="margin-top:6px;height:6px;background:rgba(255,255,255,0.05);border-radius:3px;">' +
      '<div style="width:' +
      xpPct +
      "%;height:100%;background:" +
      (xpPct > 0 ? "var(--accent)" : "rgba(255,255,255,0.1)") +

/**
 * 证书/技能训练定义
 * 可在培训中心考取
 */

const CERTIFICATES = [
  {
    id: "construction_safety",
    name: "建筑安全证",
    desc: "进入建筑工地的必要条件，减少受伤风险50%",
    requirements: { cash: 300, intelligence: 20 },
    effects: { injuryReduction: 0.5 },
    examPassRate: 0.85,
  },
  {
    id: "coding_basic",
    name: "编程基础证书",
    desc: "证明你具备基本编程能力，进入职场的重要敲门砖",
    requirements: { cash: 500, intelligence: 35 },
    effects: { codingXp: 50, intelligence: 2 },
    examPassRate: 0.65,
  },
  {
    id: "accounting_cert",
    name: "会计从业证",
    desc: "可以做会计类工作，收入稳定",
    requirements: { cash: 400, intelligence: 30 },
    effects: { accountingXp: 40, intelligence: 1 },
    examPassRate: 0.7,
  },
  {
    id: "welding_cert",
    name: "焊工证",
    desc: "特种作业证书，焊工工资高",
    requirements: { cash: 600, physique: 35 },
    effects: { weldingXp: 50, physique: 2 },
    examPassRate: 0.75,
  },
  {
    id: "driver_license",
    name: "驾照",
    desc: "可以开车，解锁送货司机等高收入工作",
    requirements: { cash: 800, agility: 25 },
    effects: { drivingXp: 40, agility: 1 },
    examPassRate: 0.6,
  },
  {
    id: "english_cert",
    name: "英语四级证书",
    desc: "证明英语水平，对外企和家教有帮助",
    requirements: { cash: 350, intelligence: 40 },
    effects: { englishXp: 60, intelligence: 2 },
    examPassRate: 0.55,
  },
  {
    id: "electrician_cert",
    name: "电工证",
    desc: "家电维修和工业电工的必备证书",
    requirements: { cash: 500, repair: 20, intelligence: 25 },
    effects: { electricianXp: 50, repair: 3 },
    examPassRate: 0.7,
  },
  {
    id: "management_cert",
    name: "管理师证书",
    desc: "职场晋升的加分项",
    requirements: { cash: 800, intelligence: 45 },
    effects: { managementXp: 50, intelligence: 3 },
    examPassRate: 0.5,
  },
];

/** 获取证书定义 */
function getCertificateById(certId) {
  return CERTIFICATES.find((c) => c.id === certId) || null;
}

/** 获取玩家可考的证书 */
function getAvailableCertificates(state) {
  return CERTIFICATES.filter((cert) => {
    if (state.certificates.includes(cert.id)) return false; // 已拥有
    const p = state.player;
    const req = cert.requirements;
    if (req.intelligence && p.intelligence < req.intelligence) return false;
    if (req.physique && p.physique < req.physique) return false;
    if (req.repair && state.skills.repair.level < req.repair) return false;
    if (req.agility && p.agility < req.agility) return false;
    return true;
  });
}

