1	/**
2	 * 技能→系统加成映射 — 技能影响多系统（吃饭/旅行/工作/银行/职场等）
3	 *
4	 * 设计理念：每项技能不仅解锁工作，还对相关的游戏系统产生渐进式加成，
5	 * 让技能培养有持续正反馈，形成"学以致用"的良性循环。
6	 */
7	
8	/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
9	function getCookingDiscount(cookingLevel) {
10	  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
11	  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
12	  return Math.min(0.7, cookingLevel * 0.008);
13	}
14	
15	/** driving技能 → 旅行AP减免 */
16	function getTravelApReduction(drivingLevel) {
17	  // 每20级减1AP，最多减5AP
18	  return Math.min(5, Math.floor(drivingLevel / 20));
19	}
20	
21	/** english技能 → 家教额外收入加成 */
22	function getTutoringBonus(englishLevel) {
23	  return englishLevel * 0.3;
24	}
25	
26	/** accounting技能 → 银行利率加成 */
27	function getBankRateBonus(accountingLevel) {
28	  // 每年最多+5%（日息约+0.00014），100级满分
29	  return accountingLevel * 0.0005;
30	}
31	
32	/** electrician技能 → 工厂类工作收入加成百分比 */
33	function getFactoryBonus(electricianLevel) {
34	  return electricianLevel * 0.005;
35	}
36	
37	/** welding技能 → 建筑类工作收入加成百分比 */
38	function getConstructionBonus(weldingLevel) {
