    var certList = document.createElement("div");
    certList.style.display = "flex";
    certList.style.gap = "6px";
    certList.style.flexWrap = "wrap";
    for (var ci = 0; ci < state.certificates.length; ci++) {
      var badge = document.createElement("span");
